//! Conformance corpus: every `tests/conformance/*.js` script is run in three
//! engine configurations and must print exactly its golden `.out` file
//! (generated by node, see `tests/update_golden.sh`):
//!
//! 1. interpreter only (`jit: false`)
//! 2. JIT mode (`jit_threshold: 0`: every eligible function is compiled on first call)
//! 3. GC-stress mode (a collection at the safepoint after every allocation), with the JIT on
//!
//! A fourth configuration (interpreter + GC stress) is also run.

use kiln::vm::Options;
use std::path::PathBuf;

fn corpus() -> Vec<PathBuf> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/conformance");
    let mut v: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "js"))
        .collect();
    v.sort();
    v
}

fn modes() -> Vec<(&'static str, Options)> {
    vec![
        (
            "interp",
            Options {
                jit: false,
                ..Options::default()
            },
        ),
        (
            "jit",
            Options {
                jit: true,
                jit_threshold: 0,
                ..Options::default()
            },
        ),
        (
            "gc-stress+jit",
            Options {
                jit: true,
                jit_threshold: 0,
                gc_stress: true,
                ..Options::default()
            },
        ),
        (
            "gc-stress+interp",
            Options {
                jit: false,
                gc_stress: true,
                ..Options::default()
            },
        ),
    ]
}

fn run_mode(idx: usize, total: usize) -> Vec<String> {
    let mut failures = Vec::new();
    let files = corpus();
    for (i, path) in files.iter().enumerate() {
        if i % total != idx {
            continue;
        }
        let src = std::fs::read_to_string(path).unwrap();
        let expected = std::fs::read_to_string(path.with_extension("out")).unwrap_or_else(|_| panic!("missing golden for {path:?}"));
        for (name, opts) in modes() {
            let s = src.clone();
            let r = kiln::with_big_stack(move || {
                let r = kiln::run_source(&s, opts);
                (r.output, r.error)
            });
            let ok = r.0 == expected && r.1.is_none();
            if !ok {
                failures.push(format!(
                    "{} [{name}]: error={:?}\n--- expected\n{}--- got\n{}",
                    path.file_name().unwrap().to_string_lossy(),
                    r.1,
                    expected,
                    r.0
                ));
            }
        }
    }
    failures
}

#[test]
fn conformance_corpus_all_modes() {
    let n = corpus().len();
    assert!(n >= 300, "corpus unexpectedly small: {n}");
    // two worker threads (the machine is shared)
    let handles: Vec<_> = (0..2).map(|i| std::thread::spawn(move || run_mode(i, 2))).collect();
    let failures: Vec<String> = handles.into_iter().flat_map(|h| h.join().unwrap()).collect();
    if !failures.is_empty() {
        for f in failures.iter().take(10) {
            eprintln!("{f}\n");
        }
        for f in &failures {
            eprintln!("FAILED: {}", f.lines().next().unwrap_or(""));
        }
        panic!("{} of {} (script, mode) runs failed", failures.len(), n * modes().len());
    }
    eprintln!("conformance: {} scripts x {} modes passed", n, modes().len());
}
